import os
import hashlib
import hmac
import secrets
import sqlite3
import re
from urllib.parse import unquote, quote
from pathlib import PurePosixPath
from functools import wraps

# Configuration
UPLOAD_BASE = '/var/app/uploads'
SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
DB_PATH = '/var/app/data/users.db'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_token(user_id):
    nonce = secrets.token_hex(16)
    payload = f"{user_id}:{nonce}"
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_token(token):
    parts = token.split(':')
    if len(parts) != 3:
        return None
    user_id, nonce, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), f"{user_id}:{nonce}".encode(), hashlib.sha256).hexdigest()
    if constant_time_compare(sig, expected):
        return int(user_id)
    return None

def require_auth(f):
    @wraps(f)
    def decorated(request, *args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        user_id = verify_token(token)
        if user_id is None:
            return {'status': 401, 'error': 'Unauthorized'}
        request.user_id = user_id
        return f(request, *args, **kwargs)
    return decorated

class PathSanitizer:
    """Multi-layer path sanitization to prevent directory traversal."""

    BLOCKED_PATTERNS = [
        re.compile(r'\.\./'),
        re.compile(r'/\.\./'),
        re.compile(r'\.\.\\'),
        re.compile(r'\\\.\.'),
        re.compile(r'%2e%2e', re.IGNORECASE),
        re.compile(r'%252e', re.IGNORECASE),
        re.compile(r'%c0%ae', re.IGNORECASE),  # overlong UTF-8
        re.compile(r'%c1%9c', re.IGNORECASE),  # overlong UTF-8 for /
    ]

    @staticmethod
    def is_safe_component(component):
        """Check if a single path component is safe."""
        if component in ('', '.', '..'):
            return component == '' or component == '.'
        # Allow alphanumeric, hyphens, underscores, dots (not leading)
        if component.startswith('.'):
            return False
        return bool(re.match(r'^[a-zA-Z0-9][a-zA-Z0-9._-]*$', component))

    @classmethod
    def sanitize_path(cls, user_path):
        """Sanitize user-provided path with defense in depth."""
        # Layer 1: Block known malicious patterns in raw input
        for pattern in cls.BLOCKED_PATTERNS:
            if pattern.search(user_path):
                raise ValueError(f"Blocked pattern detected in path")

        # Layer 2: Decode percent-encoding to get actual path
        decoded_path = unquote(user_path)

        # Layer 3: Normalize and validate each component
        parts = PurePosixPath(decoded_path).parts
        safe_parts = []
        for part in parts:
            if part == '/':
                continue
            if not cls.is_safe_component(part):
                raise ValueError(f"Invalid path component: {part}")
            safe_parts.append(part)

        return os.path.join(*safe_parts) if safe_parts else ''

def resolve_user_file(user_id, relative_path):
    """Resolve a file path within the user's upload directory."""
    # Sanitize the user-provided path
    sanitized = PathSanitizer.sanitize_path(relative_path)

    # Build the full path
    user_dir = os.path.join(UPLOAD_BASE, f"user_{user_id}")
    full_path = os.path.join(user_dir, sanitized)

    # Final safety check: ensure resolved path is under user directory
    resolved = os.path.realpath(full_path)
    base_resolved = os.path.realpath(user_dir)

    if not resolved.startswith(base_resolved):
        raise ValueError("Path traversal detected")

    return resolved

@require_auth
def handle_download(request):
    """Handle file download requests."""
    file_path = request.params.get('path', '')

    if not file_path:
        return {'status': 400, 'error': 'Missing path parameter'}

    try:
        resolved = resolve_user_file(request.user_id, file_path)
    except ValueError as e:
        return {'status': 403, 'error': str(e)}

    if not os.path.isfile(resolved):
        return {'status': 404, 'error': 'File not found'}

    with open(resolved, 'rb') as f:
        content = f.read()

    return {'status': 200, 'body': content}

@require_auth
def handle_list_files(request):
    """List files in user's directory."""
    subdir = request.params.get('dir', '')

    try:
        if subdir:
            resolved = resolve_user_file(request.user_id, subdir)
        else:
            user_dir = os.path.join(UPLOAD_BASE, f"user_{request.user_id}")
            resolved = os.path.realpath(user_dir)
    except ValueError as e:
        return {'status': 403, 'error': str(e)}

    if not os.path.isdir(resolved):
        return {'status': 404, 'error': 'Directory not found'}

    files = []
    for entry in os.scandir(resolved):
        files.append({
            'name': entry.name,
            'is_dir': entry.is_dir(),
            'size': entry.stat().st_size if entry.is_file() else 0
        })

    return {'status': 200, 'files': files}

@require_auth  
def handle_delete(request):
    """Handle file deletion."""
    file_path = request.params.get('path', '')

    if not file_path:
        return {'status': 400, 'error': 'Missing path parameter'}

    try:
        resolved = resolve_user_file(request.user_id, file_path)
    except ValueError as e:
        return {'status': 403, 'error': str(e)}

    if not os.path.exists(resolved):
        return {'status': 404, 'error': 'File not found'}

    os.remove(resolved)
    return {'status': 200, 'message': 'File deleted'}

@require_auth
def handle_share(request):
    """Share a file with another user by creating a symlink."""
    file_path = request.params.get('path', '')
    target_user = request.params.get('target_user', '')

    if not file_path or not target_user:
        return {'status': 400, 'error': 'Missing parameters'}

    try:
        target_user_id = int(target_user)
    except ValueError:
        return {'status': 400, 'error': 'Invalid target user'}

    # Verify source file exists
    try:
        source_resolved = resolve_user_file(request.user_id, file_path)
    except ValueError as e:
        return {'status': 403, 'error': str(e)}

    if not os.path.isfile(source_resolved):
        return {'status': 404, 'error': 'Source file not found'}

    # Create shared directory for target user
    target_dir = os.path.join(UPLOAD_BASE, f"user_{target_user_id}", "shared")
    os.makedirs(target_dir, exist_ok=True)

    # Create symlink in target user's shared folder
    link_name = os.path.basename(source_resolved)
    link_path = os.path.join(target_dir, link_name)

    if os.path.exists(link_path):
        os.remove(link_path)

    os.symlink(source_resolved, link_path)

    return {'status': 200, 'message': f'File shared with user {target_user_id}'}
